function coverage(requirements, matrix, executed) {
  if (requirements.length === 0) return 100;
  const known = new Set(requirements);
  const hit = new Set();
  for (const tc of executed) for (const r of matrix[tc] || []) if (known.has(r)) hit.add(r);
  return Math.round((hit.size / known.size) * 100 * 100) / 100;
}

function untested(requirements, matrix) {
  const linked = new Set(Object.values(matrix).flat());
  return requirements.filter((r) => !linked.has(r));
}

function impacted(matrix, changedRequirement) {
  return Object.keys(matrix).filter((tc) => (matrix[tc] || []).includes(changedRequirement)).sort();
}
